const TF_HOME_T14_JS="/* TaskFlow T14 · Cabecera y filtro visual, sin cambiar registros ni criterios de misión. */
(function(){
'use strict';
if(window.__tfHomeT14)return;
window.__tfHomeT14=true;
function init(){
 const bar=document.querySelector('.top-bar');
 const search=bar&&bar.querySelector('.search-container');
 if(!bar||!search||bar.querySelector('.tf14-search-filter'))return;
 const btn=document.createElement('button');
 btn.type='button';btn.className='tf14-search-filter';
 btn.setAttribute('aria-label','Filtros del inicio');
 btn.setAttribute('aria-expanded','false');
 btn.setAttribute('aria-controls','tf14FilterPopover');
 btn.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 6h18M3 12h18M3 18h18" stroke-linecap="round"/><circle cx="9" cy="6" r="2.1" fill="#092b48" stroke="currentColor"/><circle cx="16" cy="12" r="2.1" fill="#092b48" stroke="currentColor"/><circle cx="7" cy="18" r="2.1" fill="#092b48" stroke="currentColor"/></svg>';
 const pop=document.createElement('div');pop.className='tf14-filter-popover';pop.id='tf14FilterPopover';pop.hidden=true;pop.setAttribute('role','group');pop.setAttribute('aria-label','Mostrar resumen del inicio');
 const options=[['all','Todas las estadísticas'],['habits','Solo hábitos'],['tasks','Solo tareas']];
 let selected='all';
 function close(){pop.hidden=true;btn.setAttribute('aria-expanded','false')}
 function choose(value){selected=value;document.body.classList.toggle('tf14-only-habits',value==='habits');document.body.classList.toggle('tf14-only-tasks',value==='tasks');for(const el of pop.querySelectorAll('button'))el.setAttribute('aria-pressed',String(el.dataset.filter===value));close()}
 for(const [id,label] of options){const b=document.createElement('button');b.type='button';b.textContent=label;b.dataset.filter=id;b.setAttribute('aria-pressed',String(id===selected));b.addEventListener('click',()=>choose(id));pop.appendChild(b)}
 btn.addEventListener('click',e=>{e.stopPropagation();pop.hidden=!pop.hidden;btn.setAttribute('aria-expanded',String(!pop.hidden))});
 document.addEventListener('pointerdown',e=>{if(!pop.hidden&&!btn.contains(e.target)&&!pop.contains(e.target))close()},{passive:true});
 document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!pop.hidden){e.stopPropagation();close();btn.focus()}});
 bar.append(btn,pop);
}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();
})();
