  position:relative!important;display:flex!important;flex-direction:column!important;gap:0!important;
  width:min(100%,760px)!important;max-width:760px!important;height:100%!important;
  padding:0 11px 12px!important;margin:0 auto!important;overflow:hidden!important;box-sizing:border-box!important;
