const TF_T17_JS="/* TaskFlow T17 · Etapas de Mentalista y retención de desplazamiento Sung, sin alterar sus misiones. */
(function(){
'use strict';
if(window.__tfRoutineLayoutT17)return;
window.__tfRoutineLayoutT17=true;
const outer=document.getElementById('windowContainer');
const panel=document.getElementById('windowContent');
if(!outer||!panel)return;
let scheduled=false;
function schedule(){if(scheduled)return;scheduled=true;requestAnimationFrame(function(){scheduled=false;update()})}
function progress(){
 const p=panel.querySelector('.v85-routine-modal-head .v85-routine-progress-pill');
 const m=String(p&&p.textContent||'').match(/(\d+)\s*\/\s*(\d+)/);
 return m?{done:Math.max(0,Number(m[1])),total:Number(m[2])}:null;
}
function updateMental(){
 if(!outer.classList.contains('mentalist-modal'))return;
 const scroll=panel.querySelector('.v96-mentalist-scroll');
 const list=scroll&&scroll.querySelector('.v94-mentalist-list');
 const summary=scroll&&scroll.querySelector('.tfm-summary');
 if(!list||!summary)return;
 panel.classList.add('tf17-mental-layout');
 const p=progress(),count=list.querySelectorAll('.v94-mentalist-step').length;
 const total=p&&p.total>0?p.total:count;
 const done=p?Math.max(0,Math.min(p.done,total)):list.querySelectorAll('.v94-mentalist-step.done').length;
 const header=summary.querySelector('.tfm-summary-head');
 if(!header)return;
 let pill=header.querySelector('.tf17-mental-pill');
 if(!pill){
   pill=document.createElement('div');pill.className='tf17-mental-pill';
   pill.innerHTML='<span></span><small>COMPLETADAS</small>';
   const pct=header.querySelector('.tfm-summary-numeral');
   if(pct)header.insertBefore(pill,pct);else header.appendChild(pill);
 }
 const countText=done+'/'+total;
 if(pill.querySelector('span').textContent!==countText)pill.querySelector('span').textContent=countText;
 // Reutiliza la barra y los indicadores de las doce misiones existentes.
 let meter=summary.querySelector('.tfm-meter');
 if(meter&&meter.parentElement!==summary)summary.insertBefore(meter,header.nextSibling);
 let steps=summary.querySelector('.tf17-mental-steps');
 if(!steps){steps=document.createElement('div');steps.className='tf17-mental-steps';steps.setAttribute('aria-label','Etapas del protocolo');
  const before=summary.querySelector('.tfm-stats');summary.insertBefore(steps,before||null);
 }
 if(steps.children.length!==total){
  const fragment=document.createDocumentFragment();
  for(let i=0;i<total;i++){
   const node=document.createElement('span');node.className='tf17-mental-step';
   const number=document.createElement('span');number.textContent=String(i+1);node.appendChild(number);fragment.appendChild(node);
  }
  steps.replaceChildren(fragment);
  steps.style.setProperty('--tf17-total',String(total));
 }
 [...steps.children].forEach((el,i)=>{const complete=i<done;if(el.classList.contains('done')!==complete)el.classList.toggle('done',complete)});
}
function update(){
 if(!outer.classList.contains('open'))return;
 if(panel.querySelector('.v96-mentalist-scroll'))updateMental();
}
// Sung reconstruye las tarjetas al marcar: conservar el lugar del usuario en la lista.
window.addEventListener('click',function(ev){
 const el=ev.target&&ev.target.closest&&ev.target.closest('#windowContent.tf15-sung .v85-sung-list .v32-check');
 if(!el)return;
 const list=panel.querySelector('.v85-sung-list.v97-routine-scroll');
 if(!list)return;
 const oldTop=list.scrollTop;
 requestAnimationFrame(function(){
  const current=panel.querySelector('.v85-sung-list.v97-routine-scroll');
  if(current&&current.scrollTop<oldTop-4)current.scrollTop=oldTop;
 });
},true);
const mo=new MutationObserver(function(records){
 if(!outer.classList.contains('open'))return;
 for(const r of records){
  if(r.type==='childList'){
   const nodes=[...r.addedNodes];
   if(nodes.some(n=>n.nodeType===1 && (n.matches?.('.tfm-summary,.v96-mentalist-scroll,.v85-routine-modal-head')||n.querySelector?.('.tfm-summary')))){schedule();return}
  }
  if(r.type==='characterData'&&r.target.parentElement?.closest('.v85-routine-progress-pill')){schedule();return}
 }
});
mo.observe(panel,{subtree:false,childList:true,characterData:false});
const classWatcher=new MutationObserver(schedule);
classWatcher.observe(outer,{attributes:true,attributeFilter:['class']});
document.addEventListener('click',function(e){
 if(e.target.closest?.('.v94-mentalist-launch,.v94-mentalist-step,.tfm-start,.v83-core-card.sung'))schedule();
},{capture:true,passive:true});
schedule();
})();
";
const TF_AUDIO_T16_JS="/* T16: la comprobación de música guardada se realiza sin pantallazos. */
(function(){
'use strict';
if(window.__tfSilentAudioVerifyT16)return;
window.__tfSilentAudioVerifyT16=true;
const ID='tfAudioGateV13057';
function watchGate(gate){
  if(gate.dataset.tfSilentWatchT16==='1')return;
  gate.dataset.tfSilentWatchT16='1';
  const status=gate.querySelector('.tf-audio-gate-status');
  if(!status)return;
  const assess=()=>{
    const label=String(status.textContent||'').trim();
    const realDownload=/^Descargando música\s+\d+\s+de\s+\d+/i.test(label);
    const needsAction=/^La música debe quedar descargada completamente/i.test(label);
    // No mostrar un diálogo mientras solo se verifica un paquete ya almacenado.
    gate.classList.toggle('tf-audio-real-download-t16',realDownload||needsAction);
  };
  const statusObserver=new MutationObserver(assess);
  statusObserver.observe(status,{childList:true,characterData:true,subtree:true});
  assess();
}
function ready(){
  const body=document.body;if(!body)return;
  const found=document.getElementById(ID);
  if(found){watchGate(found);return;}
  const observer=new MutationObserver(records=>{
    for(const record of records){
      for(const node of record.addedNodes){
        if(node.nodeType!==1)continue;
        const gate=node.id===ID?node:node.querySelector?.('#'+ID);
        if(gate){observer.disconnect();watchGate(gate);return;}
      }
    }
  });
  observer.observe(body,{childList:true});
}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',ready,{once:true});
else ready();
})();
";
