     const part=await reader.read();if(part.done)break;touch();
     received+=part.value.byteLength;if(received>track.expectedSize)throw new Error('El tamaño de la música no coincide.');
     chunks.push(part.value);if(onProgress)onProgress(received,track.expectedSize);
    }
    blob=new Blob(chunks,{type:response.headers.get('content-type')||'audio/mpeg'});
   }else{blob=await response.blob();if(onProgress)onProgress(blob.size,track.expectedSize)}
   if(!(blob instanceof Blob)||blob.size!==track.expectedSize)throw new Error('La descarga de música no terminó completa.');
   return blob;
  }catch(error){
   lastError=error;try{if(reader)await reader.cancel()}catch(_){}
   if(attempt<2)await new Promise(resolve=>setTimeout(resolve,350*(attempt+1)));
  }finally{clearTimeout(timer)}
