function toSquareDataUrl(file){return new Promise((resolve,reject)=>{if(!file||!/^image\/(jpeg|png|webp)$/i.test(file.type||''))return reject(new Error('TYPE'));if(file.size>8*1024*1024)return reject(new Error('SIZE'));const reader=new FileReader();reader.onerror=()=>reject(new Error('READ'));reader.onload=()=>{const img=new Image();img.onerror=()=>reject(new Error('IMAGE'));img.onload=()=>{try{const w=img.naturalWidth||img.width,h=img.naturalHeight||img.height,side=Math.min(w,h);if(!side)return reject(new Error('IMAGE'));const c=document.createElement('canvas');c.width=256;c.height=256;const ctx=c.getContext('2d',{alpha:false});ctx.imageSmoothingEnabled=true;ctx.imageSmoothingQuality='high';ctx.drawImage(img,(w-side)/2,(h-side)/2,side,side,0,0,256,256);const out=c.toDataURL('image/jpeg',0.84);if(!out||out.length>850000)return reject(new Error('SIZE'));resolve(out)}catch(e){reject(e)}};img.src=String(reader.result||'')};reader.readAsDataURL(file)})}
