  let script=[...document.scripts].find(s=>s.src===src),timer=0,poll=0,done=false;
  function finish(error){if(done)return;done=true;clearTimeout(timer);clearInterval(poll);if(script){script.removeEventListener('load',loaded);script.removeEventListener('error',failed)}if(error){if(created)script.remove();reject(error)}else resolve()}
  function loaded(){if(ready())finish();else finish(new Error('SDK_UNAVAILABLE'))}
  function failed(){finish(new Error('SDK_UNAVAILABLE'))}
  if(!script){script=document.createElement('script');script.src=src;script.async=false;created=true}
  script.addEventListener('load',loaded);script.addEventListener('error',failed);
  timer=setTimeout(()=>finish(new Error('SDK_UNAVAILABLE')),10000);
  poll=setInterval(()=>{if(ready())finish()},100);
  if(created)document.head.appendChild(script);else if(ready())finish();
 });
 scriptLoads.set(src,task);task.catch(()=>{if(scriptLoads.get(src)===task)scriptLoads.delete(src)});return task;
}
